                    const { PredictiveHunterService } = await import('../../security/predictiveHunter.service.js');
                    const huntResult = await PredictiveHunterService.huntAndFixVulnerabilities('system', 'mcp-tool', targetDir);
                    return { content: [{ type: 'text', text: JSON.stringify(huntResult, null, 2) }] };

